<?php require __DIR__.'/includes/functions.php'; $title='Your bag'; $items=cart_items(); require ROOT.'/includes/header.php'; ?>
<div class="page-heading"><p class="eyebrow">GOOD CHOICES, ALL TOGETHER</p><h1>Your <span class="gradient-text">bag.</span></h1></div>
<?php if(!$items): ?><div class="empty-state glass"><i class="fa-solid fa-bag-shopping"></i><h2>A little room for something good.</h2><p>Your bag is empty. Let’s change that.</p><a class="btn btn-accent" href="<?= url('shop.php') ?>">Explore the collection ↗</a></div><?php else: ?><div class="checkout-layout"><section><?php foreach($items as $item): ?><article class="cart-row glass" data-cart-row><a href="<?= url('product.php?id='.$item['id']) ?>"><img src="<?= image_url($item['image']) ?>" alt="<?= e($item['name']) ?>" width="120" height="100"></a><div class="cart-item-info"><h3><?= e($item['name']) ?></h3><p><?= e(trim($item['size'].' / '.$item['color'],' /')) ?></p><strong><?= money(price($item)) ?></strong><form action="<?= url('action.php') ?>" method="post" class="quantity-form" data-cart-form data-ajax><?= csrf() ?><input type="hidden" name="id" value="<?= $item['id'] ?>"><input type="hidden" name="size" value="<?= e($item['size']) ?>"><input type="hidden" name="color" value="<?= e($item['color']) ?>"><label class="visually-hidden" for="qty-<?= $item['key'] ?>">Quantity for <?= e($item['name']) ?></label><input id="qty-<?= $item['key'] ?>" class="form-control quantity-input" type="number" name="quantity" min="0" max="99" value="<?= $item['quantity'] ?>" required><button class="btn btn-soft" name="action" value="cart_update">Update</button><button class="btn btn-link" name="action" value="cart_remove">Remove</button></form></div><strong class="line-total" data-unit="<?= price($item) ?>"><?= money($item['line_total']) ?></strong></article><?php endforeach; ?><a class="btn btn-link" href="<?= url('shop.php') ?>">← Keep exploring</a></section><?php require ROOT.'/includes/summary.php'; ?></div><?php endif; ?>
